<section class="hero"><p class="eyebrow">Our collection</p><h1>일상에 필요한 좋은 것들</h1><p class="muted"><?= $this->e($settings['name']) ?>에서 천천히 둘러보세요.</p></section>
<div class="toolbar"><h2>판매 상품</h2><form class="row" method="get" action="<?= $this->e($url) ?>/catalog"><input aria-label="상품 검색" name="q" value="<?= $this->e($input['q'] ?? '') ?>" placeholder="상품명 검색"><button class="secondary">검색</button></form></div>
<?php if ($products === []): ?><section class="panel empty"><h2>상품을 준비하고 있습니다</h2><?php if ($admin): ?><a class="button" href="<?= $this->e($url) ?>/products">첫 상품 등록</a><?php endif ?></section><?php endif ?>
<div class="grid"><?php foreach ($products as $item): ?><article class="product-card"><a href="<?= $this->e($url) ?>/product?id=<?= $this->e($item['id']) ?>"><?php if ($item['image']): ?><img src="<?= $this->e($url) ?>/image?file=<?= $this->e($item['image']) ?>" alt="<?= $this->e($item['name']) ?>" loading="lazy"><?php else: ?><div class="placeholder" aria-hidden="true">S</div><?php endif ?><div class="card-body"><h2><?= $this->e($item['name']) ?></h2><span class="price"><?= number_format((int) $item['min_price']) ?>원</span> <small>부터</small><?php if ((int) $item['available_stock'] === 0): ?><p><span class="badge">품절</span></p><?php endif ?></div></a></article><?php endforeach ?></div>
<nav class="pagination" aria-label="페이지"><?php if ($page_number > 1): ?><a href="<?= $this->e($url) ?>/catalog?<?= $this->e(http_build_query(['p' => $page_number - 1, 'q' => $input['q'] ?? ''])) ?>">← 이전</a><?php endif ?><?php if (count($products) === 24): ?><a href="<?= $this->e($url) ?>/catalog?<?= $this->e(http_build_query(['p' => $page_number + 1, 'q' => $input['q'] ?? ''])) ?>">다음 →</a><?php endif ?></nav>
